  (245, 'coupon.company.write', '管理商家優惠券', '新增／修改「商家優惠券」下的頁面。', 'coupon', 'ACTIVE', '2026-08-10T07:21:40.150868+00:00', '2026-08-10T07:21:40.150868+00:00', 36),
