INSERT INTO roles (id, code, name, description, category, created_at, updated_at, created_by, updated_by, owner_type, owner_code, is_admin, parent_role_id) VALUES
  (88, 'ota_tc_admin', 'OTA團控管理員', '統管 OTA 團控全部頁面；可管理本租戶成員並移交管理員身分，不可維護角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, true, NULL),
  (89, 'supplier_admin', '供應商超級管理員', '供應商體系最高權限：產品、訂單、元件、團控、供應商檔案全開；可管理本租戶成員與角色，並移交管理員身分。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, true, NULL),
  (90, 'component_admin', '元件供應商管理員', '維護元件資源與供應商檔案；可管理本供應商成員並移交管理員身分，不可維護角色。', 'supplier', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, true, 89),
  (91, 'product_op', '商品OP', '建立與維護旅遊商品；不管理成員與角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 98),
  (92, 'order_op', '訂單OP', '處理線路訂單、憑證管理與訂單分析；不管理成員與角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 98),
  (93, 'tour_control_op', '團控OP', '執行團控管理作業；不管理成員與角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 98),
  (94, 'component_op', '元件OP', '維護元件資源與供應商檔案；不管理成員與角色。', 'supplier', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 90),
  (95, 'ota_tc_leader', 'OTA團控OP主管', '承擔 OTA 團控全部頁面作業，含商品歸集表與特殊方案配置；不管理成員與角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 88),
  (96, 'ota_tc_staff', 'OTA團控OP', '處理 OTA 團控日常頁面，不含商品歸集表與特殊方案配置；不管理成員與角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 88),
  (97, 'ota_tc_lion', '雄獅內部訂單OP', '僅處理雄獅內部訂單頁面；不管理成員與角色。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, false, 88),
  (98, 'product_supplier_admin', '商品供應商管理員', '維護旅遊商品、線路訂單與憑證、團控；可管理本供應商成員與角色，並移交管理員身分。', 'company', '2026-08-10T07:21:40.150868+00:00', '2026-08-14T08:29:43.220026+00:00', 'system', 'system', 'SYSTEM', NULL, true, 89)
